//! Native finite-difference/volume transport in an explicit reference frame.
use super::Dynamic;
use super::Frame;
use super::Handle;
use super::Installer;
use super::LIMIT;
use super::OpError;
use super::RuleError;
use super::api;
use super::err;
use super::grid_size;
use super::object_binding;
use super::payload;
fn valid(
    dims: &[usize],
    spacing: &[f64],
    data: &[f64],
    dt: f64,
    steps: usize,
    history: bool,
) -> Result<(), OpError> {
    grid_size(dims)?;
    let cells = dims.iter().product::<usize>();
    if data.len() != cells
        || spacing.len() != dims.len()
        || spacing.iter().any(|x| !x.is_finite() || *x <= 0.0)
        || dt <= 0.0
        || !dt.is_finite()
        || steps == 0
        || steps > 8192
        || cells.checked_mul(steps).is_none_or(|n| n > 8_388_608)
        || history && cells.checked_mul(steps + 1).is_none_or(|n| n > LIMIT)
    {
        return Err(err(
            "transport spacing/data/time or work/allocation budget invalid",
        ));
    }
    Ok(())
}
fn finish(
    f: &Frame,
    data: Vec<f64>,
    dims: Vec<usize>,
) -> Result<Dynamic, OpError> {
    payload(f, data, dims)
}
