fn stable(
    spacing: &[f64],
    dt: f64,
    velocity: &[f64],
    diffusivity: f64,
) -> Result<(), OpError> {
    let adv = velocity
        .iter()
        .zip(spacing)
        .map(|(c, h)| c.abs() * dt / h)
        .sum::<f64>();
    let diffusion = spacing
        .iter()
        .map(|h| 2.0 * diffusivity * dt / (h * h))
        .sum::<f64>();
    if !adv.is_finite() || !diffusion.is_finite() || adv + diffusion > 1.0 + 32.0 * f64::EPSILON {
        return Err(err("explicit transport CFL/diffusion limit exceeded"));
    }
    Ok(())
}
